#!/usr/bin/env python3
"""Embed the JSON data files in ``data/`` as Kotlin raw strings.

Kotlin Multiplatform common code has no portable resource API, so the JSON data
is compiled in as string constants instead. Re-run this script whenever a file in
``data/`` changes (e.g. when syncing with upstream archeryutils):

    python3 scripts/generate_data.py
"""

import re
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
OUT = ROOT / "src/commonMain/kotlin/io/github/retbrown/archeryutils"
PACKAGE = "io.github.retbrown.archeryutils"

# (data sub-directory, generated file name, Kotlin object name, output package suffix)
GROUPS = [
    ("rounds", "RoundData.kt", "RoundData", "rounds"),
    ("classifications", "ClassificationData.kt", "ClassificationData", "classifications"),
    ("handicaps", "HandicapData.kt", "HandicapData", "handicaps"),
]


def prop_name(stem: str) -> str:
    """Convert a file stem such as ``AGB_outdoor_metric`` to ``AGB_OUTDOOR_METRIC``."""
    return re.sub(r"[^0-9A-Za-z]+", "_", stem).upper()


def main() -> None:
    for subdir, filename, obj, pkg_suffix in GROUPS:
        lines = [
            "// GENERATED by scripts/generate_data.py from data/" + subdir + "/*.json. DO NOT EDIT.",
            f"package {PACKAGE}.{pkg_suffix}",
            "",
            f"internal object {obj} {{",
        ]
        for path in sorted((ROOT / "data" / subdir).glob("*.json")):
            text = path.read_text(encoding="utf-8")
            assert '"""' not in text and len(text.encode()) < 60000, path
            lines.append(f"    /** Contents of `{path.name}`. */")
            lines.append(f'    val {prop_name(path.stem)}: String = """{text}"""')
            lines.append("")
        lines[-1] = "}"
        target = OUT / pkg_suffix / filename
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text("\n".join(lines) + "\n", encoding="utf-8")
        print("wrote", target.relative_to(ROOT))


if __name__ == "__main__":
    main()
